// MaskedTextBox's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/masked_text_box.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The mask (Mask); a view onto the provider. A new mask keeps as much of the text as it takes (the assigned characters, without prompts or literals, placed again from the first position), or starts empty, and raises mask_changed. Throws std::invalid_argument for an invalid mask (MaskedTextProvider).
template <typename Declaring>
struct MaskedTextBoxMaskCapability {
    PropertyView<std::string, MaskedTextBoxMaskCapability<Declaring>> mask;

    static void assign(MaskedTextBoxMaskCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.mask), std::move(incoming));
    }

    static std::string read(const MaskedTextBoxMaskCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.mask);
        return current;
    }
};

// The culture whose separators and currency symbol the mask's placeholders show (Culture); a view onto the provider. A change keeps as much of the text as the mask takes.
template <typename Declaring>
struct MaskedTextBoxCultureCapability {
    PropertyView<MaskCulture, MaskedTextBoxCultureCapability<Declaring>> culture;

    static void assign(MaskedTextBoxCultureCapability& capability, MaskCulture incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.culture), std::move(incoming));
    }

    static MaskCulture read(const MaskedTextBoxCultureCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        MaskCulture current = control.read_view(capability.culture);
        return current;
    }
};

// The text in text_mask_format (Text); a view onto the provider (under an empty mask, the editor's text). A write clears the box and places the text from the first position, literals in it matching the mask's literals, as place_text does; refused text leaves the box unchanged and raises mask_input_rejected instead of throwing (place_text reports the result). A placed text raises text_changed.
template <typename Declaring>
struct MaskedTextBoxTextCapability {
    PropertyView<std::string, MaskedTextBoxTextCapability<Declaring>> text;

    static void assign(MaskedTextBoxTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.text), std::move(incoming));
    }

    static std::string read(const MaskedTextBoxTextCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.text);
        return current;
    }
};

// What text includes (TextMaskFormat): literals, prompts, both or neither. A change raises text_changed when text changes; an unknown format throws std::invalid_argument.
template <typename Declaring>
struct MaskedTextBoxTextMaskFormatCapability {
    PropertyCell<MaskTextFormat, MaskedTextBoxTextMaskFormatCapability<Declaring>> text_mask_format{MaskTextFormat::include_literals};

    static void assign(MaskedTextBoxTextMaskFormatCapability& capability, MaskTextFormat incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.text_mask_format), incoming);
        if (!capability.text_mask_format.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.text_mask_format));
    }
};

