// With it off (the default), a paste keeps the characters the mask takes and reports each one it drops; with it on, one refused character refuses the whole paste (RejectInputOnFirstFailure).
template <typename Declaring>
struct MaskedTextBoxRejectInputOnFirstFailureCapability {
    PropertyCell<bool, MaskedTextBoxRejectInputOnFirstFailureCapability<Declaring>> reject_input_on_first_failure{};

    static void assign(MaskedTextBoxRejectInputOnFirstFailureCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.reject_input_on_first_failure), incoming);
        if (!capability.reject_input_on_first_failure.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.reject_input_on_first_failure));
    }
};

