// Every MaskedTextBox capability, in the order the declaring class takes them.
template <typename Declaring>
struct MaskedTextBoxCapabilities : public MaskedTextBoxMaskCapability<Declaring>,
                                   public MaskedTextBoxCultureCapability<Declaring>,
                                   public MaskedTextBoxTextCapability<Declaring>,
                                   public MaskedTextBoxTextMaskFormatCapability<Declaring>,
                                   public MaskedTextBoxPromptCharacterCapability<Declaring>,
                                   public MaskedTextBoxAllowPromptAsInputCapability<Declaring>,
                                   public MaskedTextBoxAsciiOnlyCapability<Declaring>,
                                   public MaskedTextBoxSkipLiteralsCapability<Declaring>,
                                   public MaskedTextBoxResetOnPromptCapability<Declaring>,
                                   public MaskedTextBoxResetOnSpaceCapability<Declaring>,
                                   public MaskedTextBoxRejectInputOnFirstFailureCapability<Declaring>,
                                   public MaskedTextBoxOverwriteModeCapability<Declaring>,
                                   public MaskedTextBoxReadOnlyCapability<Declaring> {};

